def transform(grid):
    out=[row[:] for row in grid]
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid))
    colors={v for row in grid for v in row if v!=bg}
    for color in colors:
        pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
        for r,c in pts:
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                # A pair along a diagonal establishes the direction; extend outward from each end.
                if (0<=r-dr<len(grid) and 0<=c-dc<len(grid[0]) and grid[r-dr][c-dc]==color):
                    nr,nc=r+dr,c+dc
                    while 0<=nr<len(out) and 0<=nc<len(out[0]) and out[nr][nc]==bg:
                        out[nr][nc]=color
                        nr+=dr;nc+=dc
    return out
